/**
 * Dependency-free ledger reduction.
 *
 * An event has the shape:
 *   { id: string, account: string, cents: number, kind: "credit" | "debit" }
 *
 * Credits add cents and debits subtract cents.  All balances are accumulated
 * with BigInt internally so the arithmetic never loses precision, then
 * converted back to safe JavaScript integers before being returned.
 */

export class LedgerError extends Error {
  constructor(message) {
    super(message);
    this.name = "LedgerError";
  }
}

const KINDS = new Set(["credit", "debit"]);

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function validateEvent(event, index) {
  const where = `event ${index + 1}`;
  if (!isPlainObject(event)) {
    throw new LedgerError(`${where} must be a JSON object`);
  }

  if (typeof event.id !== "string" || event.id.length === 0 || event.id.trim() === "") {
    throw new LedgerError(`${where} has an invalid id (expected a nonempty string)`);
  }
  if (
    typeof event.account !== "string" ||
    event.account.length === 0 ||
    event.account.trim() === ""
  ) {
    throw new LedgerError(`${where} has an invalid account (expected a nonempty string)`);
  }
  if (
    typeof event.cents !== "number" ||
    !Number.isSafeInteger(event.cents) ||
    event.cents < 0
  ) {
    throw new LedgerError(
      `${where} has an invalid cents value (expected a nonnegative safe integer)`
    );
  }
  if (typeof event.kind !== "string" || !KINDS.has(event.kind)) {
    throw new LedgerError(`${where} has an invalid kind (expected "credit" or "debit")`);
  }

  return {
    id: event.id,
    account: event.account,
    cents: event.cents,
    kind: event.kind,
  };
}

function sameEvent(a, b) {
  // `-0 === 0` is true; that is intentional for JSON numeric equality.
  return (
    a.id === b.id &&
    a.account === b.account &&
    a.cents === b.cents &&
    a.kind === b.kind
  );
}

/** Compare two strings by Unicode code point (not UTF-16 code unit). */
export function compareByCodePoint(a, b) {
  const left = Array.from(a, (ch) => ch.codePointAt(0));
  const right = Array.from(b, (ch) => ch.codePointAt(0));
  const length = Math.min(left.length, right.length);
  for (let i = 0; i < length; i += 1) {
    if (left[i] !== right[i]) return left[i] - right[i];
  }
  return left.length - right.length;
}

/**
 * Parse UTF-8 JSONL text into event objects.  Blank (whitespace-only) lines
 * are ignored.  Syntax errors and non-object records are rejected.
 */
export function parseJsonl(text) {
  if (typeof text !== "string") {
    throw new LedgerError("input must be text");
  }

  const events = [];
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (line.trim() === "") continue;

    let event;
    try {
      event = JSON.parse(line);
    } catch (error) {
      throw new LedgerError(`malformed JSON on line ${i + 1}: ${error.message}`);
    }
    if (!isPlainObject(event)) {
      throw new LedgerError(`line ${i + 1} must contain a JSON object`);
    }
    events.push(event);
  }
  return events;
}

function normalizeOptions(options) {
  if (options === undefined || options === null) return {};
  if (typeof options === "string") return { account: options };
  if (typeof options !== "object" || Array.isArray(options)) {
    throw new LedgerError("options must be an object or account name");
  }
  return options;
}

/**
 * Reduce events (an iterable of event objects, or JSONL text) to the ledger
 * summary.  `options.account` (or a string second argument) filters the
 * emitted accounts and netCents, but not the event counts.
 *
 * @param {Iterable<object>|string} events
 * @param {{account?: string}|string} [options]
 * @returns {{uniqueEvents: number, duplicateEvents: number,
 *            accounts: Array<{account: string, balanceCents: number}>,
 *            netCents: number}}
 */
export function reduceEvents(events, options) {
  const opts = normalizeOptions(options);

  let records;
  if (typeof events === "string") {
    records = parseJsonl(events);
  } else if (events != null && typeof events[Symbol.iterator] === "function") {
    records = Array.from(events);
  } else {
    throw new LedgerError("events must be an iterable or JSONL text");
  }

  const byId = new Map();
  let duplicateEvents = 0;

  for (let i = 0; i < records.length; i += 1) {
    const event = validateEvent(records[i], i);
    const previous = byId.get(event.id);
    if (previous === undefined) {
      byId.set(event.id, event);
    } else if (sameEvent(previous, event)) {
      duplicateEvents += 1;
    } else {
      throw new LedgerError(
        `conflicting records share id ${JSON.stringify(event.id)}`
      );
    }
  }

  const balances = new Map();
  for (const event of byId.values()) {
    const delta = BigInt(event.cents) * (event.kind === "credit" ? 1n : -1n);
    balances.set(event.account, (balances.get(event.account) ?? 0n) + delta);
  }

  let selected = [...balances.entries()];
  if (opts.account !== undefined) {
    if (typeof opts.account !== "string" || opts.account.length === 0) {
      throw new LedgerError("account filter must be a nonempty string");
    }
    selected = selected.filter(([account]) => account === opts.account);
  }

  selected.sort(([a], [b]) => compareByCodePoint(a, b));

  let net = 0n;
  const accounts = selected.map(([account, balance]) => {
    net += balance;
    return { account, balanceCents: toSafeNumber(balance, `balance for ${account}`) };
  });

  return {
    uniqueEvents: byId.size,
    duplicateEvents,
    accounts,
    netCents: toSafeNumber(net, "net total"),
  };
}

function toSafeNumber(value, label) {
  if (value > BigInt(Number.MAX_SAFE_INTEGER) || value < BigInt(Number.MIN_SAFE_INTEGER)) {
    throw new LedgerError(`${label} exceeds the safe integer range`);
  }
  return Number(value);
}

// Convenient aliases so the reducer can be imported under natural names.
export const reduceLedger = reduceEvents;
export const reconcile = reduceEvents;
export const reducer = reduceEvents;
export default reduceEvents;

#!/usr/bin/env node
/**
 * Ledger reconciliation CLI.
 *
 * Usage: node reconcile.mjs INPUT OUTPUT [--account NAME]
 *
 * INPUT is UTF-8 JSONL.  The output file is only replaced after the entire
 * input has been read, parsed, validated and reduced successfully.
 */

import {
  closeSync,
  mkdirSync,
  openSync,
  readFileSync,
  renameSync,
  unlinkSync,
  writeFileSync,
} from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { LedgerError, parseJsonl, reduceEvents } from "./ledger.mjs";

const USAGE = "usage: node reconcile.mjs INPUT OUTPUT [--account NAME]";

export function parseArgs(argv) {
  let input;
  let output;
  let account;
  let hasAccount = false;

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];

    if (arg === "--account" || arg.startsWith("--account=")) {
      if (hasAccount) throw new LedgerError("--account may only be given once");
      let value;
      if (arg === "--account") {
        if (i + 1 >= argv.length) {
          throw new LedgerError("--account requires a value");
        }
        value = argv[i + 1];
        i += 1;
      } else {
        value = arg.slice("--account=".length);
      }
      if (value.length === 0) {
        throw new LedgerError("--account requires a nonempty value");
      }
      account = value;
      hasAccount = true;
    } else if (arg === "--help" || arg === "-h") {
      return { help: true };
    } else if (arg.startsWith("-")) {
      throw new LedgerError(`unknown option ${JSON.stringify(arg)}`);
    } else if (input === undefined) {
      input = arg;
    } else if (output === undefined) {
      output = arg;
    } else {
      throw new LedgerError("too many positional arguments");
    }
  }

  if (input === undefined || output === undefined) {
    throw new LedgerError("both INPUT and OUTPUT are required");
  }
  if (input.length === 0 || output.length === 0) {
    throw new LedgerError("INPUT and OUTPUT must be nonempty paths");
  }

  return { input, output, account };
}

/**
 * Write to a temporary file in the destination directory and atomically
 * rename it over OUTPUT.  If anything fails, OUTPUT is left untouched.
 */
export function writeOutputAtomically(outputPath, contents) {
  const directory = dirname(outputPath);
  mkdirSync(directory, { recursive: true });

  const temporary = join(
    directory,
    `.${basename(outputPath)}.tmp-${process.pid}-${Date.now()}-${Math.random()
      .toString(36)
      .slice(2)}`
  );

  let fd;
  try {
    fd = openSync(temporary, "wx", 0o600);
    writeFileSync(fd, contents, { encoding: "utf8" });
    closeSync(fd);
    fd = undefined;
    renameSync(temporary, outputPath);
  } catch (error) {
    if (fd !== undefined) {
      try {
        closeSync(fd);
      } catch {
        // Ignore secondary close errors.
      }
    }
    try {
      unlinkSync(temporary);
    } catch {
      // The temporary file may never have been created.
    }
    throw error;
  }
}

export function run(argv) {
  const args = parseArgs(argv);
  if (args.help) {
    process.stdout.write(`${USAGE}\n`);
    return 0;
  }

  // Read and validate everything before touching OUTPUT.
  let text;
  try {
    text = readFileSync(args.input, "utf8");
  } catch (error) {
    throw new LedgerError(`cannot read input ${JSON.stringify(args.input)}: ${error.message}`);
  }

  const result = reduceEvents(parseJsonl(text), {
    ...(args.account === undefined ? {} : { account: args.account }),
  });

  writeOutputAtomically(args.output, `${JSON.stringify(result, null, 2)}\n`);
  return 0;
}

export function main(argv = process.argv.slice(2)) {
  try {
    return run(argv);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`error: ${message}\n`);
    return 1;
  }
}

const invokedDirectly =
  process.argv[1] !== undefined &&
  fileURLToPath(import.meta.url) === resolve(process.argv[1]);

if (invokedDirectly) {
  process.exitCode = main();
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

import {
  LedgerError,
  compareByCodePoint,
  parseJsonl,
  reduceEvents,
} from "./ledger.mjs";

const CLI = fileURLToPath(new URL("./reconcile.mjs", import.meta.url));

function makeTempDir(t) {
  const directory = mkdtempSync(join(tmpdir(), "ledger-test-"));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  return directory;
}

function runCli(args, cwd) {
  return spawnSync(process.execPath, [CLI, ...args], {
    encoding: "utf8",
    cwd,
  });
}

function event(id, account, cents, kind) {
  return { id, account, cents, kind };
}

test("reducer totals credits and debits and deduplicates identical ids", () => {
  const result = reduceEvents([
    event("a", "alpha", 100, "credit"),
    event("b", "beta", 40, "debit"),
    event("a", "alpha", 100, "credit"),
    event("a", "alpha", 100, "credit"),
  ]);

  assert.deepEqual(result, {
    uniqueEvents: 2,
    duplicateEvents: 2,
    accounts: [
      { account: "alpha", balanceCents: 100 },
      { account: "beta", balanceCents: -40 },
    ],
    netCents: 60,
  });
});

test("conflicting records sharing an id invalidate the whole input", () => {
  assert.throws(
    () =>
      reduceEvents([
        event("same", "alpha", 10, "credit"),
        event("same", "alpha", 11, "credit"),
      ]),
    (error) => error instanceof LedgerError && /conflicting/.test(error.message)
  );

  assert.throws(
    () =>
      reduceEvents([
        event("same", "alpha", 10, "credit"),
        event("same", "alpha", 10, "debit"),
      ]),
    LedgerError
  );
});

test("integer arithmetic stays exact near the safe-integer boundary", () => {
  const result = reduceEvents([
    event("1", "big", Number.MAX_SAFE_INTEGER, "credit"),
    event("2", "big", Number.MAX_SAFE_INTEGER - 1, "debit"),
    event("3", "big", 1, "credit"),
  ]);

  assert.deepEqual(result.accounts, [{ account: "big", balanceCents: 2 }]);
  assert.equal(result.netCents, 2);

  const exact = reduceEvents([
    event("1", "big", 9007199254740990, "credit"),
    event("2", "big", 1, "debit"),
  ]);
  assert.equal(exact.netCents, 9007199254740989);
  assert.equal(exact.accounts[0].balanceCents, 9007199254740989);

  // Zero-cent events and duplicate zero-cent events are legal.
  assert.deepEqual(
    reduceEvents([
      event("z", "zero", 0, "credit"),
      event("z", "zero", 0, "credit"),
    ]),
    {
      uniqueEvents: 1,
      duplicateEvents: 1,
      accounts: [{ account: "zero", balanceCents: 0 }],
      netCents: 0,
    }
  );
});

test("invalid fields and malformed JSON are rejected", () => {
  const invalidEvents = [
    [null],
    [[]],
    [event("", "a", 1, "credit")],
    [event("  ", "a", 1, "credit")],
    [event("id", "", 1, "credit")],
    [event("id", "  ", 1, "credit")],
    [event("id", "a", -1, "credit")],
    [event("id", "a", 1.5, "credit")],
    [event("id", "a", Number.MAX_SAFE_INTEGER + 1, "credit")],
    [event("id", "a", "1", "credit")],
    [event("id", "a", 1, "transfer")],
    [event("id", "a", 1)],
    [{ id: "id", account: "a", kind: "credit" }],
  ];

  for (const events of invalidEvents) {
    assert.throws(
      () => reduceEvents(events),
      LedgerError,
      `expected rejection for ${JSON.stringify(events)}`
    );
  }

  assert.throws(() => parseJsonl('{"id":"a",}\n'), /malformed JSON/);
  assert.throws(() => parseJsonl("[]\n"), LedgerError);
  assert.throws(() => parseJsonl("null\n"), LedgerError);
});

test("--account filtering changes accounts and net but not event counts", () => {
  const events = [
    event("1", "alpha", 10, "credit"),
    event("2", "beta", 20, "credit"),
    event("3", "alpha", 4, "debit"),
    event("2", "beta", 20, "credit"),
  ];

  assert.deepEqual(reduceEvents(events, { account: "alpha" }), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: "alpha", balanceCents: 6 }],
    netCents: 6,
  });

  // The filter also accepts the shorthand string argument.
  assert.deepEqual(reduceEvents(events, "beta"), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: "beta", balanceCents: 20 }],
    netCents: 20,
  });

  assert.deepEqual(reduceEvents(events, { account: "missing" }), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [],
    netCents: 0,
  });
});

test("accounts are sorted by Unicode code point", () => {
  const names = ["\u{10000}", "\uE000", "ä", "a", "Z", "账户甲", "账户乙"];
  const result = reduceEvents(names.map((name, i) => event(String(i), name, 1, "credit")));

  assert.deepEqual(
    result.accounts.map((entry) => entry.account),
    ["Z", "a", "ä", "\uE000", "\u{10000}", "账户乙", "账户甲"]
  );

  // UTF-16 code-unit sorting would put the astral character before U+E000.
  assert.ok(compareByCodePoint("\uE000", "\u{10000}") < 0);
  assert.ok(compareByCodePoint("\u{10000}", "\uE000") > 0);
});

test("blank lines are ignored when parsing JSONL", () => {
  const text =
    '\r\n{"id":"a","account":"x","cents":1,"kind":"credit"}\n   \n\t\n' +
    '{"id":"a","account":"x","cents":1,"kind":"credit"}\r\n';
  const events = parseJsonl(text);
  assert.equal(events.length, 2);

  assert.deepEqual(reduceEvents(text), {
    uniqueEvents: 1,
    duplicateEvents: 1,
    accounts: [{ account: "x", balanceCents: 1 }],
    netCents: 1,
  });
});

test("CLI writes the expected JSON and creates parent directories", (t) => {
  const dir = makeTempDir(t);
  const input = join(dir, "input.jsonl");
  const output = join(dir, "nested", "deeper", "result.json");
  writeFileSync(
    input,
    [
      '{"id":"1","account":"alpha","cents":15,"kind":"credit"}',
      "",
      '{"id":"2","account":"beta","cents":5,"kind":"debit"}',
      '{"id":"1","account":"alpha","cents":15,"kind":"credit"}',
      "",
    ].join("\n")
  );

  const run = runCli([input, output], dir);
  assert.equal(run.status, 0, run.stderr);
  assert.equal(run.stderr, "");

  const parsed = JSON.parse(readFileSync(output, "utf8"));
  assert.deepEqual(parsed, {
    uniqueEvents: 2,
    duplicateEvents: 1,
    accounts: [
      { account: "alpha", balanceCents: 15 },
      { account: "beta", balanceCents: -5 },
    ],
    netCents: 10,
  });
});

test("CLI --account filters output while keeping whole-input counts", (t) => {
  const dir = makeTempDir(t);
  const input = join(dir, "input.jsonl");
  const output = join(dir, "result.json");
  writeFileSync(
    input,
    [
      '{"id":"1","account":"alpha","cents":15,"kind":"credit"}',
      '{"id":"2","account":"beta","cents":5,"kind":"debit"}',
      '{"id":"2","account":"beta","cents":5,"kind":"debit"}',
    ].join("\n")
  );

  const run = runCli([input, output, "--account", "beta"], dir);
  assert.equal(run.status, 0, run.stderr);
  assert.deepEqual(JSON.parse(readFileSync(output, "utf8")), {
    uniqueEvents: 2,
    duplicateEvents: 1,
    accounts: [{ account: "beta", balanceCents: -5 }],
    netCents: -5,
  });
});

test("CLI preserves an existing output when input is malformed", (t) => {
  const dir = makeTempDir(t);
  const input = join(dir, "bad.jsonl");
  const output = join(dir, "result.json");
  writeFileSync(input, '{"id":"1","account":"a","cents":1,"kind":"credit"}\nnot json\n');
  writeFileSync(output, "EXISTING OUTPUT\n");

  const run = runCli([input, output], dir);
  assert.notEqual(run.status, 0);
  assert.match(run.stderr, /error:/);
  assert.equal(readFileSync(output, "utf8"), "EXISTING OUTPUT\n");
});

test("CLI preserves an existing output on invalid or conflicting events", (t) => {
  const dir = makeTempDir(t);
  const output = join(dir, "result.json");

  const cases = [
    '{"id":"1","account":"a","cents":-2,"kind":"credit"}\n',
    '{"id":"1","account":"a","cents":2,"kind":"credit"}\n' +
      '{"id":"1","account":"a","cents":3,"kind":"credit"}\n',
    '{"id":"1","account":"a","cents":2,"kind":"other"}\n',
  ];

  for (let i = 0; i < cases.length; i += 1) {
    const input = join(dir, `invalid-${i}.jsonl`);
    writeFileSync(input, cases[i]);
    writeFileSync(output, `KEEP ${i}\n`);

    const run = runCli([input, output], dir);
    assert.notEqual(run.status, 0);
    assert.equal(readFileSync(output, "utf8"), `KEEP ${i}\n`);
  }
});

test("CLI rejects missing arguments and unknown options without writing output", (t) => {
  const dir = makeTempDir(t);
  const output = join(dir, "result.json");

  const missingOutput = runCli([join(dir, "no-such-input.jsonl")], dir);
  assert.notEqual(missingOutput.status, 0);
  assert.match(missingOutput.stderr, /usage|required/i);

  const unknownOption = runCli([join(dir, "no-such-input.jsonl"), output, "--bogus"], dir);
  assert.notEqual(unknownOption.status, 0);
  assert.match(unknownOption.stderr, /unknown option/);

  const noInput = runCli([join(dir, "missing.jsonl"), output], dir);
  assert.notEqual(noInput.status, 0);
  assert.match(noInput.stderr, /cannot read input/);
});

